import java.io.IOException;
import java.util.StringTokenizer;
import java.util.ArrayList;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Arrays;

public class Main {
    static int n;
    static ArrayList<Integer>[] adj;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = br.readLine();
        }
        if (line == null) return;

        n = Integer.parseInt(line.trim());
        adj = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int i = 0; i < n - 1; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            adj[u].add(v);
            adj[v].add(u);
        }

        // 1ª BFS para encontrar uma extremidade do diâmetro
        int[] dist = new int[n + 1];
        int[] parent = new int[n + 1];
        bfs(1, dist, parent);

        int nodeA = 1;
        for (int i = 2; i <= n; i++) {
            if (dist[i] > dist[nodeA]) {
                nodeA = i;
            }
        }

        // 2ª BFS para encontrar a outra extremidade e o diâmetro
        bfs(nodeA, dist, parent);
        int nodeB = nodeA;
        for (int i = 1; i <= n; i++) {
            if (dist[i] > dist[nodeB]) {
                nodeB = i;
            }
        }

        int d = dist[nodeB];
        // Reconstrói o caminho de nodeA até nodeB
        int[] path = new int[d + 1];
        int curr = nodeB;
        for (int i = d; i >= 0; i--) {
            path[i] = curr;
            curr = parent[curr];
        }

        long count = 0;

        if (d % 2 == 1) {
            // Centro é uma aresta entre path[d / 2] e path[d / 2 + 1]
            int c1 = path[d / 2];
            int c2 = path[d / 2 + 1];
            int k = d / 2;

            long cnt1 = countNodesAtDepth(c1, c2, k);
            long cnt2 = countNodesAtDepth(c2, c1, k);
            count = cnt1 * cnt2;
        } else {
            // Centro é um único vértice: path[d / 2]
            int c = path[d / 2];
            int k = d / 2;

            long sum = 0;
            long sumSq = 0;
            for (int neighbor : adj[c]) {
                long cnt = countNodesAtDepth(neighbor, c, k - 1);
                sum += cnt;
                sumSq += cnt * cnt;
            }
            count = (sum * sum - sumSq) / 2;
        }

        System.out.println(d + 1);
        System.out.println(count);
    }

    static void bfs(int start, int[] dist, int[] parent) {
        Arrays.fill(dist, -1);
        Queue<Integer> queue = new ArrayDeque<>();
        dist[start] = 0;
        parent[start] = 0;
        queue.add(start);

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    queue.add(v);
                }
            }
        }
    }

    static long countNodesAtDepth(int start, int blocked, int targetDepth) {
        if (targetDepth < 0) return 0;
        Queue<Integer> q = new ArrayDeque<>();
        Queue<Integer> depthQ = new ArrayDeque<>();
        q.add(start);
        depthQ.add(0);

        long count = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            int curD = depthQ.poll();

            if (curD == targetDepth) {
                count++;
            } else if (curD < targetDepth) {
                for (int v : adj[u]) {
                    if (v != blocked) {
                        q.add(v);
                        depthQ.add(curD + 1);
                    }
                }
            }
            // Para não voltar ao nó bloqueado / pai, na BFS simples:
            // mas como é uma árvore e evitamos voltar, basta registrar visitados ou passar pai.
        }
        return countDfs(start, blocked, 0, targetDepth);
    }

    // Usando DFS para contar nós a uma distância exata para evitar overhead de fila
    static long countDfs(int u, int p, int d, int target) {
        if (d == target) {
            return 1;
        }
        long count = 0;
        for (int v : adj[u]) {
            if (v != p) {
                count += countDfs(v, u, d + 1, target);
            }
        }
        return count;
    }
}
